#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char *name;
    char *value;
} SFDLine;

typedef struct {
    SFDLine *lines;
    int line_count;
} SFDFile;

void SFDParseLine(FILE *sfd, SFDFile *sf, struct font_data *d) {
    char line[MAX_LINE_LENGTH];
    int ch, temp;
    char tok[MAX_LINE_LENGTH];
    int i;

    while (fgets(line, MAX_LINE_LENGTH, sfd)) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;

        if (sscanf(line, "%s", tok) != 1) continue;

        ch = fgetc(sfd);
        if (ch == EOF) break;

        if (strmatch(tok, "ContextPos2:")) {
            parseContextPos(sfd, sf, d, true);
        } else if (strmatch(tok, "ContextPos:")) {
            parseContextPos(sfd, sf, d, false);
        } else if (strmatch(tok, "Group:")) {
            parseGroup(sfd, sf, d);
        } else if (strmatch(tok, "GroupKern:")) {
            parseGroupKern(sfd, sf, d);
        } else if (strmatch(tok, "GroupVKern:")) {
            parseGroupVKern(sfd, sf, d);
        } else if (strmatch(tok, "MacIndic2:")) {
            parseMacIndic(sfd, sf, d, true);
        } else if (strmatch(tok, "MacIndic:")) {
            parseMacIndic(sfd, sf, d, false);
        } else if (strmatch(tok, "MacFeat:")) {
            parseMacFeatures(sfd, tok);
        } else if (strmatch(tok, "TtfTable:")) {
            parseTtfTable(sfd, sf, d);
        } else if (strmatch(tok, "ShortTable:")) {
            parseShortTable(sfd, sf, d);
        } else {
            IError("Unknown SFD line: %s", tok);
            exit(1);
        }
    }
}

